using System;
using System.Collections.Generic;
using System.IO;
using System.Web.Script.Serialization;
using System.Web.UI;
using System.Web.UI.WebControls;

namespace InformationWeb.Controls.SimsMember
{
    public partial class MainLogin : System.Web.UI.UserControl
    {
        protected string SectionTitle = "THÔNG TIN";

        protected void Page_Load(object sender, EventArgs e)
        {
            if (!IsPostBack)
            {
                BindNews();
            }
        }

        private void BindNews()
        {
            try
            {
                string strPath = Server.MapPath("~/App_Data/MainLoginNews.json");
                if (!File.Exists(strPath))
                {
                    return;
                }

                string strJson = File.ReadAllText(strPath);
                JavaScriptSerializer objSerializer = new JavaScriptSerializer();
                MainLoginNewsConfig objConfig = objSerializer.Deserialize<MainLoginNewsConfig>(strJson);

                if (objConfig == null || objConfig.Items == null)
                {
                    return;
                }

                if (!string.IsNullOrEmpty(objConfig.SectionTitle))
                {
                    SectionTitle = objConfig.SectionTitle;
                }

                rptNews.DataSource = objConfig.Items;
                rptNews.DataBind();
            }
            catch
            {
            }
        }

        protected string GetHiddenClass(object objValue)
        {
            if (objValue == null)
            {
                return "d-none";
            }

            bool blnVisible = false;
            if (objValue is bool)
            {
                blnVisible = (bool)objValue;
            }
            else
            {
                bool.TryParse(Convert.ToString(objValue), out blnVisible);
            }

            return blnVisible ? string.Empty : "d-none";
        }

        public class MainLoginNewsConfig
        {
            public string SectionTitle { get; set; }
            public List<MainLoginNewsItem> Items { get; set; }
        }

        public class MainLoginNewsItem
        {
            public string Image { get; set; }
            public string Category { get; set; }
            public bool ShowCategory { get; set; }
            public string Url { get; set; }
            public string Title { get; set; }
            public string SubTitle { get; set; }
            public bool ShowSubTitle { get; set; }
            public string Description { get; set; }
            public string Date { get; set; }
            public string Author { get; set; }
        }
    }
}

